1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type Result = { premium: number } | { payout: number; remainingCap: number };
23	
24	const PROCESSING_FEE = 5;
25	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
26	
27	const BASE_PREMIUMS: Record<string, number> = {
28	  sword: 100,
29	  amulet: 60,
30	  staff: 80,
31	  potion: 40,
32	  rune: 25,
33	};
34	
35	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
36	
37	const sumBasePremiums = (items: Item[]): number =>
38	  items.reduce((total, item) => total + basePremiumOf(item), 0);
39	
40	const quotePremium = (items: Item[]): number => {
41	  const base = sumBasePremiums(items);
42	  // Keep the surcharge additive (base + base * rate). The algebraically
43	  // equivalent base * (1 + rate) yields 110.00000000000001 for base 100,
44	  // which Math.ceil turns into a premium that is 1 G too high.
45	  const firstInsuranceSurcharge = base * FIRST_INSURANCE_SURCHARGE_RATE;
46	  return Math.ceil(base + firstInsuranceSurcharge + PROCESSING_FEE);
47	};
48	
49	export const runScenario = (scenario: Scenario): Result[] =>
50	  scenario.steps.map((step) => {
51	    if (step.op === "quote") return { premium: quotePremium(step.items) };
52	    throw new Error(`Unsupported step: ${step.op}`);
53	  });
